class Solution {
 vector<vector<int>> g;vector<int> cnt,price;
 bool path(int u,int parent,int target){
  if(u==target){++cnt[u];return true;}
  for(int v:g[u])if(v!=parent&&path(v,u,target)){++cnt[u];return true;}
  return false;
 }
 pair<long long,long long> dfs(int u,int p){
  long long full=1LL*cnt[u]*price[u],half=1LL*cnt[u]*(price[u]/2);
  for(int v:g[u])if(v!=p){auto c=dfs(v,u);full+=min(c.first,c.second);half+=c.first;}
  return {full,half};
 }
public:
 int minimumTotalPrice(int n,vector<vector<int>>& edges,vector<int>& price,vector<vector<int>>& trips){
  g.assign(n,{});cnt.assign(n,0);this->price=price;
  for(auto &e:edges){g[e[0]].push_back(e[1]);g[e[1]].push_back(e[0]);}
  for(auto &t:trips)path(t[0],-1,t[1]);
  auto p=dfs(0,-1);return (int)min(p.first,p.second);
 }
};
